  function add_purchase(p_member_id in number, p_amount in number) return number is
    l_points_earned number;
    l_current_points loyalty_members.points%type;
    l_new_points loyalty_members.points%type;
  begin
    insert into loyalty_purchases (member_id, amount) values (p_member_id, p_amount);

    -- Calculate points earned using points_rules package
    l_points_earned := points_rules.points_for(p_amount);

    -- Get current points
    select points into l_current_points from loyalty_members where member_id = p_member_id;

    -- Update points balance
    update loyalty_members
      set points = points + l_points_earned
      where member_id = p_member_id;

